import {
  Errored,
  For,
  Loading,
  Show,
  action,
  affects,
  createEffect,
  createMemo,
  createOptimistic,
  createSignal,
  createStore,
  isPending,
  latest,
  onSettled,
  refresh,
} from "solid-js";
import type {
  PluginCredentialDescriptor,
  PluginCredentialInspection,
  PluginsCredentialsInspectResult,
} from "../../../../packages/gateway-protocol/src/schema/plugin-credentials.ts";
import {
  isSecretRef,
  isValidSecretRef,
  type SecretRef,
} from "../../../../src/secrets/ref-contract.ts";
import type { ConfigNodeRenderParams } from "../../components/config-form.node.shared.ts";
import { DialogHeader } from "../../components/solid/dialog-header.tsx";
import { Icon } from "../../components/solid/icon.tsx";
import "../../components/modal-dialog.tsx";
import { InlineAlert } from "../../components/solid/inline-alert.tsx";
import { registerPluginManagementEnglish } from "../../i18n/locales/en-plugin-management.ts";
import { REDACTED_SENTINEL } from "../../lib/config-form-utils.ts";
import { formatUiError } from "../../lib/format-error.ts";
import type { GatewayConnectionScope } from "../../lib/gateway-connection-lifecycle.ts";
import type { GatewayPageBinding } from "../../lib/gateway-page-binding.ts";
import {
  clearCompositionEnd,
  isComposingKeyboardEvent,
  recordCompositionEnd,
} from "../../lib/ime.ts";
import "./credential-editor.css";
import "./custom-elements.ts";
import { t } from "../../lib/reactive/i18n.ts";

registerPluginManagementEnglish();
const credentialReferenceParts = ["provider", "id"] as const;
const credentialSources = ["env", "file", "exec", "store"] as const;

export type PluginCredentialEditorContext = {
  pluginId: string;
  baseHash: string | null;
  gateway: Pick<GatewayPageBinding, "capture" | "isCurrent" | "epoch" | "connected" | "client">;
  canInspect: boolean;
  getPresentationLifetime: () => Promise<void>;
  saveError?: string | null;
  /** Adapter stages through field.onPatch and awaits that exact config-owner write. */
  onCommit: (path: Array<string | number>, value: unknown) => Promise<boolean>;
  onDiscard: () => Promise<boolean>;
};
type CredentialField = Pick<ConfigNodeRenderParams, "path" | "value" | "disabled"> & {
  descriptionId?: string;
};
type CredentialOperation = {
  kind: "save" | "discard";
  current: () => boolean;
};

export type PluginCredentialEditorProps = {
  field: CredentialField;
  descriptor: PluginCredentialDescriptor;
  context: PluginCredentialEditorContext;
};

export function PluginCredentialEditor(props: PluginCredentialEditorProps) {
  // Keep revealed values clearable; async computations retain completion, never the payload.
  const [inspection, setInspection] = createSignal<PluginCredentialInspection | null>(null);
  const [inspectionRequest, setInspectionRequest] = createSignal<{ promise: Promise<void> }>();
  const inspectionComplete = createMemo(
    () => inspectionRequest()?.promise.then(() => null) ?? null,
  );
  const inspectionPending = createMemo<boolean>(
    () =>
      inspectionRequest()?.promise.then(
        () => false,
        () => false,
      ) ?? false,
    { loadingValue: true },
  );
  const loading = () => isPending(inspectionPending) || latest(inspectionPending);
  const [operationRequest, setOperationRequest] = createSignal<{ promise: Promise<void> }>();
  const operationComplete = createMemo(() => operationRequest()?.promise.then(() => null) ?? null, {
    loadingValue: null,
  });
  // Revision and unacknowledged-write outcomes are separate from rejected commands.
  const [error, setError] = createSignal("");
  const [dialogOpen, setDialogOpen] = createSignal(false);
  const [reference, setReference] = createStore<SecretRef>({
    source: "env",
    provider: "default",
    id: "",
  });
  const [literal, setLiteral] = createSignal("");
  const [revealed, setRevealed] = createSignal(false);
  const [operation, setOperation] = createOptimistic<CredentialOperation | undefined>(undefined);
  const operationKind = () => {
    const value = operation();
    return value?.current() ? value.kind : undefined;
  };
  const saving = () => operationKind() === "save";
  const cancelling = () => operationKind() === "discard";
  let referenceSubmitted = false;
  let referenceTrigger: HTMLElement | null = null;
  let generation = 0;
  let connection: GatewayConnectionScope | null = null;
  let active = true;
  let pending: CredentialOperation | undefined;
  let literalInput: HTMLInputElement | undefined;
  let referenceSourceSelect: HTMLSelectElement | undefined;

  // Reinspect the Gateway credential when its field, revision, or connection changes.
  createEffect(
    () => {
      const { pluginId, baseHash, gateway, canInspect } = props.context;
      const field = JSON.stringify([pluginId, props.field.path]);
      return {
        field,
        gateway,
        client: gateway.client,
        epoch: gateway.epoch,
        baseHash,
        connected: gateway.connected,
        canInspect,
        identity: JSON.stringify([field, baseHash, gateway.epoch, canInspect]),
      };
    },
    (next, previous) => {
      if (
        next.identity === previous?.identity &&
        next.gateway === previous?.gateway &&
        next.client === previous?.client
      ) {
        return;
      }
      const sourceChanged =
        next.gateway !== previous?.gateway ||
        next.client !== previous?.client ||
        next.field !== previous?.field ||
        (next.connected && !next.canInspect);
      // Snapshot this revision's editing intent and error copy; neither retriggers inspection.
      const [wasOpen, wasSaving, staleMessage] = [
        dialogOpen(),
        pending?.kind === "save",
        t("pluginsPage.credentials.stale"),
      ] as const;
      setRevealed(false);
      // Other settings can advance the revision before this field's blur commit.
      // Only retiring the field's identity or access may discard its uncommitted key.
      if (sourceChanged) {
        setLiteral("");
        setDialogOpen(false);
        referenceSubmitted = false;
        setReference(() => ({ source: "env", provider: "default", id: "" }));
      }
      if (sourceChanged || next.epoch !== previous?.epoch) {
        pending = undefined;
        setOperationRequest(undefined);
      }
      setInspectionRequest(undefined);
      setInspection((current) =>
        sourceChanged ? null : current?.kind === "literal" ? { kind: "literal" } : current,
      );
      generation++;
      if (wasOpen && !wasSaving && !sourceChanged && next.baseHash !== previous?.baseHash) {
        setInspection(null);
        setError(staleMessage);
        return;
      }
      void inspect();
    },
  );

  onSettled(() => () => {
    active = false;
    generation++;
    referenceSubmitted = false;
    referenceTrigger = null;
  });

  function inspect(reveal = false) {
    const { gateway, pluginId, baseHash, canInspect } = props.context;
    const capturedConnection = gateway.capture();
    const requestGeneration = ++generation;
    connection = capturedConnection;
    setError("");
    setInspectionRequest(undefined);
    if (!canInspect || !capturedConnection || !baseHash) {
      return Promise.resolve();
    }
    const completed = (async () => {
      try {
        const result = await capturedConnection.client.request<PluginsCredentialsInspectResult>(
          "plugins.credentials.inspect",
          { pluginId, path: props.field.path, baseHash, ...(reveal ? { reveal: true } : {}) },
        );
        if (requestGeneration !== generation || !gateway.isCurrent(capturedConnection)) {
          return;
        }
        if (result.baseHash !== props.context.baseHash) {
          throw new Error(t("pluginsPage.credentials.stale"));
        }
        setInspection(
          result.credential.kind === "literal" && !reveal ? { kind: "literal" } : result.credential,
        );
        setRevealed(
          reveal && result.credential.kind === "literal" && result.credential.value !== undefined,
        );
      } catch (cause) {
        if (requestGeneration === generation && gateway.isCurrent(capturedConnection)) {
          throw cause;
        }
      }
    })();
    setInspectionRequest({ promise: completed });
    // The boundary presents admitted failures; callers only await inspection settlement.
    return completed.catch(() => undefined);
  }

  function toggleReveal() {
    if (revealed()) {
      setRevealed(false);
      if (inspection()?.kind === "literal") {
        setInspection({ kind: "literal" });
      }
    } else if (literal()) {
      setRevealed(true);
    } else {
      void inspect(true);
    }
  }

  function openReference(event: MouseEvent) {
    referenceTrigger = event.currentTarget instanceof HTMLElement ? event.currentTarget : null;
    referenceSubmitted = false;
    const value = inspection();
    setReference(() =>
      value?.kind === "reference"
        ? { ...value.ref }
        : { source: "env", provider: "default", id: "" },
    );
    setDialogOpen(true);
  }

  function enteredLiteral(input: HTMLInputElement) {
    // Native blur can precede Solid's signal commit. Revealing a stored key is not an edit.
    return literal() || input.value !== literalValue() ? input.value : "";
  }

  async function patch(value: string | SecretRef) {
    if (
      props.field.disabled ||
      pending ||
      !props.context.canInspect ||
      !connection ||
      !props.context.gateway.isCurrent(connection)
    ) {
      return;
    }
    setInspectionRequest(undefined);
    return commitOrDiscardReference(value);
  }

  async function cancelReference() {
    if (pending) {
      return;
    }
    if (!referenceSubmitted) {
      setDialogOpen(false);
      return;
    }
    return commitOrDiscardReference(undefined);
  }

  async function commitOrDiscardReference(value: string | SecretRef | undefined) {
    setError("");
    const gateway = props.context.gateway;
    const retired = props.context.getPresentationLifetime();
    const capturedConnection = connection;
    const owner = JSON.stringify([props.context.pluginId, props.field.path]);
    const current = () =>
      pending === admitted &&
      active &&
      props.context.getPresentationLifetime() === retired &&
      props.context.gateway === gateway &&
      capturedConnection !== null &&
      gateway.isCurrent(capturedConnection) &&
      JSON.stringify([props.context.pluginId, props.field.path]) === owner;
    const admitted: CredentialOperation = {
      kind: value === undefined ? "discard" : "save",
      current,
    };
    // Admission is synchronous; Solid publishes the pending presentation after this task.
    pending = admitted;
    if (value !== undefined) {
      referenceSubmitted ||= dialogOpen();
    }
    // Start the authoritative write before holding the presentation transaction.
    const completed = (async () => {
      try {
        const acknowledged = await (value === undefined
          ? props.context.onDiscard()
          : props.context.onCommit(props.field.path, value));
        if (!current()) {
          return;
        }
        if (acknowledged) {
          referenceSubmitted = false;
          setDialogOpen(false);
          if (value !== undefined) {
            setLiteral("");
          }
          await inspect();
        } else {
          setError(
            props.context.saveError ||
              t(
                value === undefined
                  ? "configView.discardUnconfirmed"
                  : "pluginsPage.credentials.saveFailed",
              ),
          );
        }
      } catch (cause) {
        if (current()) {
          throw cause;
        }
      }
    })();
    // Publish the completion before the action holds its saving presentation.
    const result = Promise.resolve().then(() => presentOperation(admitted, completed, retired));
    setOperationRequest({ promise: result });
    // Feedback observes rejection; retired event callers only await settlement.
    return result.catch(() => undefined);
  }

  const presentOperation = action(function* (
    admitted: CredentialOperation,
    completed: Promise<void>,
    retired: Promise<void>,
  ) {
    try {
      if (admitted.current()) {
        setOperation(admitted);
        affects(inspectionComplete);
      }
      yield Promise.race([completed, retired]);
      if (admitted.current()) {
        yield refresh(inspectionComplete);
      }
    } finally {
      if (pending === admitted) {
        pending = undefined;
      }
    }
  });

  const environment = () => {
    const credential = inspection();
    return credential?.kind === "environment" ? credential.envVar : null;
  };
  const blocked = () =>
    props.field.disabled ||
    !props.context.gateway.connected ||
    !props.context.canInspect ||
    loading() ||
    saving() ||
    cancelling() ||
    !inspection();
  const failure = () => error() || props.context.saveError;
  const Failure = (feedback: { message: string; dialog?: boolean }) => (
    <>
      {feedback.dialog ? (
        <InlineAlert tone="danger" role="alert">
          {feedback.message}
        </InlineAlert>
      ) : (
        <div role="alert">
          {feedback.message}
          <button
            class="btn btn--sm"
            onClick={() => void (literal() ? patch(literal()) : inspect())}
          >
            {t("common.retry")}
          </button>
        </div>
      )}
    </>
  );
  const Feedback = (feedback: { dialog?: boolean }) => (
    <Show when={!saving() && !cancelling()}>
      <Show
        when={failure()}
        fallback={
          <Loading on={inspectionRequest()}>
            <Errored
              fallback={(cause) => (
                <Failure message={formatUiError(cause())} dialog={feedback.dialog} />
              )}
            >
              {operationComplete()}
              {inspectionComplete()}
            </Errored>
          </Loading>
        }
      >
        {(message) => <Failure message={message()} dialog={feedback.dialog} />}
      </Show>
    </Show>
  );
  const configured = () =>
    props.field.value === REDACTED_SENTINEL || inspection()?.kind === "literal";
  const isReference = () => inspection()?.kind === "reference" || isSecretRef(props.field.value);
  const disabled = () =>
    props.field.disabled ||
    saving() ||
    !props.context.canInspect ||
    !props.context.gateway.connected ||
    !props.context.baseHash;
  const referenceSource = () => {
    const credential = inspection();
    return credential?.kind === "reference"
      ? credential.ref.source
      : isSecretRef(props.field.value)
        ? props.field.value.source
        : "";
  };
  const referenceId = () => {
    const credential = inspection();
    return credential?.kind === "reference" ? credential.ref.id : undefined;
  };
  const literalValue = () => {
    const credential = inspection();
    return (
      literal() || (revealed() && credential?.kind === "literal" ? (credential.value ?? "") : "")
    );
  };
  const unresolved = () => {
    const credential = inspection();
    return credential?.kind === "reference" && credential.unresolved;
  };

  return (
    <openclaw-plugin-credential-editor>
      <div class="plugin-credential">
        {isReference() || environment() ? (
          <div class="plugin-credential__reference">
            <span>
              {environment()
                ? t("pluginsPage.credentials.environment", { name: environment()! })
                : t("pluginsPage.credentials.fromSource", { source: referenceSource() })}
            </span>
            {referenceId() !== undefined ? <code>{referenceId()}</code> : null}
            <button
              class="btn btn--sm"
              aria-label={`${t(environment() ? "pluginsPage.credentials.viewSource" : "pluginsPage.credentials.editReference")}: ${props.descriptor.label}`}
              aria-describedby={props.field.descriptionId}
              disabled={loading() || !inspection() || !props.context.canInspect}
              onClick={openReference}
            >
              {t(
                environment()
                  ? "pluginsPage.credentials.viewSource"
                  : "pluginsPage.credentials.editReference",
              )}
            </button>
          </div>
        ) : (
          <>
            <div
              class="plugin-credential__input settings-secret"
              onFocusOut={(event) => {
                clearCompositionEnd(event);
                if (
                  event.relatedTarget instanceof Element &&
                  event.relatedTarget.closest(".plugin-credential__input") === event.currentTarget
                ) {
                  return;
                }
                const value = literalInput ? enteredLiteral(literalInput) : "";
                if (value) {
                  void patch(value);
                }
              }}
            >
              <input
                ref={(input) => (literalInput = input)}
                class="settings-input"
                aria-label={props.descriptor.label}
                aria-describedby={props.field.descriptionId}
                autocomplete="off"
                spellcheck="false"
                type={revealed() ? "text" : "password"}
                value={literalValue()}
                placeholder={
                  configured()
                    ? t("pluginsPage.credentials.stored")
                    : (props.descriptor.placeholder ?? "")
                }
                disabled={disabled()}
                onInput={(event) => setLiteral(event.currentTarget.value)}
                onCompositionEnd={recordCompositionEnd}
                onKeyUp={clearCompositionEnd}
                onKeyDown={(event) => {
                  if (isComposingKeyboardEvent(event)) {
                    return;
                  }
                  const value = enteredLiteral(event.currentTarget);
                  if (event.key === "Enter" && value) {
                    event.preventDefault();
                    void patch(value);
                  }
                }}
              />
              <button
                class="settings-secret__toggle"
                type="button"
                aria-label={`${t(revealed() ? "pluginsPage.credentials.hide" : "pluginsPage.credentials.reveal")}: ${props.descriptor.label}`}
                aria-pressed={revealed() ? "true" : "false"}
                disabled={
                  disabled() || loading() || (!literal() && inspection()?.kind !== "literal")
                }
                onClick={toggleReveal}
              >
                <Icon name={revealed() ? "eyeOff" : "eye"} />
              </button>
            </div>
            <div class="plugin-credential__links">
              {props.descriptor.signupUrl ? (
                <a href={props.descriptor.signupUrl} target="_blank" rel="noopener noreferrer">
                  {t("pluginsPage.credentials.signup")}
                  <Icon name="externalLink" />
                </a>
              ) : null}
              <button
                class="btn btn--ghost btn--sm"
                aria-label={`${t("pluginsPage.credentials.useReference")}: ${props.descriptor.label}`}
                aria-describedby={props.field.descriptionId}
                disabled={disabled() || loading() || !inspection() || !props.context.canInspect}
                onClick={openReference}
              >
                {t("pluginsPage.credentials.useReference")}
              </button>
            </div>
            {configured() ? <small>{t("pluginsPage.credentials.replace")}</small> : null}
          </>
        )}
        {loading() ? (
          <span role="status" class="muted">
            {t("common.loading")}
          </span>
        ) : null}
        {inspection()?.kind === "invalid" ? (
          <span role="alert">{t("pluginsPage.credentials.invalidStored")}</span>
        ) : null}
        {!dialogOpen() ? <Feedback /> : null}
        {dialogOpen() ? (
          <openclaw-modal-dialog
            prop:initialFocus={() =>
              referenceSourceSelect?.isConnected ? referenceSourceSelect : null
            }
            ref={(dialog) => dialog.setReturnFocusTarget(referenceTrigger)}
            label={`${t("pluginsPage.credentials.referenceTitle")}: ${props.descriptor.label}`}
            onModal-cancel={(event: Event) => {
              event.preventDefault();
              void cancelReference();
            }}
          >
            <section class="oc-dialog plugin-credential__dialog">
              <DialogHeader
                title={t("pluginsPage.credentials.referenceTitle")}
                description={
                  <p>
                    {environment()
                      ? t("pluginsPage.credentials.environmentHelp", { name: environment()! })
                      : t("pluginsPage.credentials.referenceHelp")}
                  </p>
                }
                closeDisabled={saving() || cancelling()}
                onClose={() => void cancelReference()}
              />
              <div class="oc-dialog__body">
                {environment() ? null : (
                  <>
                    <label>
                      {t("pluginsPage.credentials.source")}
                      <select
                        ref={(element) => {
                          referenceSourceSelect = element;
                        }}
                        autofocus
                        class="settings-input"
                        aria-label={t("pluginsPage.credentials.source")}
                        value={reference.source}
                        disabled={blocked()}
                        onChange={(event) => {
                          const source = credentialSources.find(
                            (entry) => entry === event.currentTarget.value,
                          );
                          if (source) {
                            setReference((draft) => {
                              draft.source = source;
                            });
                          }
                        }}
                      >
                        <For each={credentialSources}>
                          {(source) => (
                            <option value={source} selected={source === reference.source}>
                              {t(`pluginsPage.credentials.sources.${source}`)}
                            </option>
                          )}
                        </For>
                      </select>
                    </label>
                    <For each={credentialReferenceParts}>
                      {(key) => (
                        <label>
                          {t(`pluginsPage.credentials.${key === "id" ? "identifier" : key}`)}
                          <input
                            class="settings-input"
                            value={reference[key]}
                            disabled={blocked()}
                            onInput={(event) =>
                              setReference((draft) => {
                                draft[key] = event.currentTarget.value;
                              })
                            }
                          />
                        </label>
                      )}
                    </For>
                    <p class="muted">{t(`pluginsPage.credentials.help.${reference.source}`)}</p>
                    {unresolved() ? (
                      <InlineAlert tone="warning">
                        {t("pluginsPage.credentials.unresolved")}
                      </InlineAlert>
                    ) : null}
                  </>
                )}
                <Feedback dialog />
              </div>
              {environment() && (inspection() || loading()) ? null : (
                <openclaw-modal-actions class="oc-dialog__footer">
                  <button
                    class="btn"
                    disabled={saving() || cancelling()}
                    onClick={() => void cancelReference()}
                  >
                    {t("common.cancel")}
                  </button>
                  {!inspection() && !loading() ? (
                    <button class="btn" onClick={() => void inspect()}>
                      {t("common.retry")}
                    </button>
                  ) : null}
                  {!environment() ? (
                    <button
                      class="btn primary"
                      disabled={blocked() || !isValidSecretRef(reference)}
                      onClick={() =>
                        void patch({
                          source: reference.source,
                          provider: reference.provider,
                          id: reference.id,
                        })
                      }
                    >
                      {saving() ? t("common.saving") : t("common.save")}
                    </button>
                  ) : null}
                </openclaw-modal-actions>
              )}
            </section>
          </openclaw-modal-dialog>
        ) : null}
      </div>
    </openclaw-plugin-credential-editor>
  );
}
